// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title AdvancedMixer
 * @dev Un sistema di mixing che utilizza Merkle tree e firme digitali per la privacy
 *
 * Questo contratto implementa un mixer che:
 * 1. Memorizza solo la Merkle root invece di tutti i depositi
 * 2. Utilizza firme digitali invece di ZK-proof per l'autenticazione
 * 3. Previene replay attacks con mapping di commitment spesi
 * 4. Supporta aggiornamenti della Merkle root da parte di un gestore autorizzato
 */
contract AdvancedMixer is ReentrancyGuard, Ownable {
    using ECDSA for bytes32;

    // =========================================== Events ============================================

    /// @dev Event emesso quando viene aggiornata la Merkle root
    event MerkleRootUpdated(
        bytes32 indexed oldRoot,
        bytes32 indexed newRoot,
        uint256 timestamp
    );

    /// @dev Event emesso quando viene effettuato un prelievo
    event Withdrawal(
        bytes32 indexed commitment,
        address indexed recipient,
        uint256 amount,
        uint256 timestamp
    );

    /// @dev Event emesso quando viene registrato un nuovo deposito
    event DepositRegistered(
        bytes32 indexed commitment,
        uint256 amount,
        uint256 timestamp
    );

    // ======================================= State variables =======================================

    /// @dev La Merkle root corrente che rappresenta tutti i depositi
    bytes32 public merkleRoot;

    /// @dev L'importo fisso per ogni deposito
    uint256 public immutable depositAmount;

    /// @dev Mapping per tracciare i commitment già spesi
    mapping(bytes32 => bool) public spentCommitments;

    /// @dev Contatore dei depositi totali
    uint256 public totalDeposits;

    /// @dev Indirizzo del gestore che può aggiornare la Merkle root
    address public merkleManager;

    // ======================================= Modifiers =======================================

    /// @dev Modifier per verificare che solo il merkleManager possa aggiornare la root
    modifier onlyMerkleManager() {
        require(
            msg.sender == merkleManager,
            "AdvancedMixer: only merkle manager"
        );
        _;
    }

    // ======================================= Constructor =======================================

    /**
     * @dev Costruttore del contratto
     * @param _depositAmount L'importo fisso per ogni deposito
     * @param _merkleManager L'indirizzo del gestore della Merkle root
     */
    constructor(
        uint256 _depositAmount,
        address _merkleManager
    ) Ownable(msg.sender) {
        require(
            _depositAmount > 0,
            "AdvancedMixer: deposit amount must be positive"
        );
        require(
            _merkleManager != address(0),
            "AdvancedMixer: merkle manager cannot be zero"
        );

        depositAmount = _depositAmount;
        merkleManager = _merkleManager;
    }

    // ======================================= Core Functions =======================================

    /**
     * @notice Funzione per prelevare fondi utilizzando una Merkle proof e una firma
     * @param _signature La firma della richiesta di prelievo
     * @param _pubKey La chiave pubblica rivelata per il prelievo
     * @param _recipient L'indirizzo destinatario dei fondi
     * @param _merkleProof La prova Merkle per dimostrare l'inclusione del commitment
     */
    function withdraw(
        bytes calldata _signature,
        bytes calldata _pubKey,
        address payable _recipient,
        bytes32[] calldata _merkleProof
    ) external nonReentrant {
        require(
            _recipient != address(0),
            "AdvancedMixer: recipient cannot be zero"
        );
        require(
            _pubKey.length > 0,
            "AdvancedMixer: public key cannot be empty"
        );
        require(
            _signature.length == 65,
            "AdvancedMixer: invalid signature length"
        );

        // 1. Calcola il commitment (foglia del Merkle tree)
        bytes32 leaf = keccak256(_pubKey);

        // 2. Verifica che il commitment non sia già stato speso
        require(
            !spentCommitments[leaf],
            "AdvancedMixer: commitment already spent"
        );

        // 3. Verifica la Merkle proof
        bool isValidProof = MerkleProof.verify(_merkleProof, merkleRoot, leaf);
        require(isValidProof, "AdvancedMixer: invalid Merkle proof");

        // 4. Verifica la firma
        bytes32 messageHash = keccak256(abi.encodePacked(_recipient));
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );
        address signer = ECDSA.recover(ethSignedMessageHash, _signature);

        // Verifica che la firma sia valida e corrisponda alla chiave pubblica
        require(signer != address(0), "AdvancedMixer: invalid signature");

        // Opzionale: verifica che il signer corrisponda all'indirizzo derivato dalla pubKey
        // Questo è un controllo aggiuntivo di sicurezza
        address derivedAddress = _deriveAddressFromPubKey(_pubKey);
        require(signer == derivedAddress, "AdvancedMixer: signature mismatch");

        // 5. Marca il commitment come speso
        spentCommitments[leaf] = true;

        // 6. Invia i fondi
        (bool success, ) = _recipient.call{value: depositAmount}("");
        require(success, "AdvancedMixer: transfer failed");

        // 7. Emetti l'evento
        emit Withdrawal(leaf, _recipient, depositAmount, block.timestamp);
    }

    /**
     * @notice Aggiorna la Merkle root (solo per il merkleManager)
     * @param _newRoot La nuova Merkle root
     */
    function updateMerkleRoot(bytes32 _newRoot) external onlyMerkleManager {
        bytes32 oldRoot = merkleRoot;
        merkleRoot = _newRoot;

        emit MerkleRootUpdated(oldRoot, _newRoot, block.timestamp);
    }

    /**
     * @notice Registra un nuovo deposito (solo per il merkleManager)
     * @param _commitment Il commitment del deposito
     */
    function registerDeposit(bytes32 _commitment) external onlyMerkleManager {
        totalDeposits++;
        emit DepositRegistered(_commitment, depositAmount, block.timestamp);
    }

    // ======================================= Management Functions =======================================

    /**
     * @notice Cambia il merkle manager (solo per il proprietario)
     * @param _newManager Il nuovo indirizzo del merkle manager
     */
    function setMerkleManager(address _newManager) external onlyOwner {
        require(
            _newManager != address(0),
            "AdvancedMixer: new manager cannot be zero"
        );
        merkleManager = _newManager;
    }

    /**
     * @notice Permette al proprietario di prelevare ETH dal contratto in caso di emergenza
     * @param _amount L'importo da prelevare
     * @param _recipient Il destinatario dei fondi
     */
    function emergencyWithdraw(
        uint256 _amount,
        address payable _recipient
    ) external onlyOwner {
        require(
            _recipient != address(0),
            "AdvancedMixer: recipient cannot be zero"
        );
        require(
            _amount <= address(this).balance,
            "AdvancedMixer: insufficient balance"
        );

        (bool success, ) = _recipient.call{value: _amount}("");
        require(success, "AdvancedMixer: emergency withdrawal failed");
    }

    // ======================================= View Functions =======================================

    /**
     * @notice Verifica se un commitment è stato speso
     * @param _commitment Il commitment da verificare
     * @return True se il commitment è stato speso
     */
    function isCommitmentSpent(
        bytes32 _commitment
    ) external view returns (bool) {
        return spentCommitments[_commitment];
    }

    /**
     * @notice Ottiene il bilancio del contratto
     * @return Il bilancio in ETH
     */
    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }

    // ======================================= Helper Functions =======================================

    /**
     * @dev Deriva un indirizzo da una chiave pubblica
     * @param _pubKey La chiave pubblica
     * @return L'indirizzo derivato
     */
    function _deriveAddressFromPubKey(
        bytes calldata _pubKey
    ) internal pure returns (address) {
        // Per semplicità, usiamo l'hash della chiave pubblica come indirizzo
        // In un'implementazione reale, dovresti usare la derivazione ECDSA corretta
        bytes32 hash = keccak256(_pubKey);
        return address(uint160(uint256(hash)));
    }

    /**
     * @dev Calcola il commitment da una chiave pubblica
     * @param _pubKey La chiave pubblica
     * @return Il commitment calcolato
     */
    function calculateCommitment(
        bytes calldata _pubKey
    ) external pure returns (bytes32) {
        return keccak256(_pubKey);
    }

    // ======================================= Receive Function =======================================

    /**
     * @dev Permette al contratto di ricevere ETH
     */
    receive() external payable {
        // Il contratto può ricevere ETH per i depositi
    }
}

